INSERT OR IGNORE INTO state(key,value) SELECT 'short-candidates-converted:20261005',json_group_array(v.id) FROM videos v JOIN matches m ON m.video_id=v.id WHERE v.format='SHORT_CANDIDATE' AND v.available=1 AND m.performer_id='missioned-souls' AND m.status='CONFIRMED' AND NOT EXISTS(SELECT 1 FROM exclusions e WHERE e.video_id=v.id AND e.performer_id=m.performer_id);
UPDATE videos SET format='SHORT',format_locked=1 WHERE format='SHORT_CANDIDATE' AND available=1 AND EXISTS(SELECT 1 FROM matches m WHERE m.video_id=videos.id AND m.performer_id='missioned-souls' AND m.status='CONFIRMED' AND NOT EXISTS(SELECT 1 FROM exclusions e WHERE e.video_id=m.video_id AND e.performer_id=m.performer_id));
